import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;

public class UomMasterTest {
    public static void main(String[] args) {
        WebDriver driver = new ChromeDriver();
        driver.get("https://gc-dev.centralindia.cloudapp.azure.com/ambica/auth/login");
        driver.findElement(By.xpath("//button[contains(text(),'Master Data')]")).click();
        driver.findElement(By.xpath("//a[contains(text(),'UoM Master')]")).click();
        driver.findElement(By.xpath("//button[contains(text(),'ADD UOM')]")).click();
        driver.findElement(By.id("uomName")).sendKeys("FEET");
        driver.findElement(By.xpath("//button[contains(text(),'Submit')]")).click();
        driver.quit();
    }
}
